export const code = async (inputs) => {
  const payload = inputs.rawPayload || {};
  const objectKind = payload.object_kind || (payload.object_attributes ? payload.object_attributes.object_kind : 'merge_request');
  const objectAttributes = payload.object_attributes || {};
  const projectCode = payload.project ? payload.project.path_with_namespace : 'PROJ-CORE';
  const actor = payload.user ? payload.user.username : (payload.actor || 'unknown.user');

  let labels = [];
  if (Array.isArray(payload.labels)) {
    labels = payload.labels.map(l => typeof l === 'string' ? l : l.title);
  } else if (Array.isArray(objectAttributes.labels)) {
    labels = objectAttributes.labels.map(l => typeof l === 'string' ? l : l.title);
  }

  const isBug = labels.includes('bug') || labels.includes('type::bug');
  const createdAt = objectAttributes.created_at || payload.created_at || new Date().toISOString();
  const eventTime = objectAttributes.updated_at || payload.event_time || new Date().toISOString();

  return {
    project_code: projectCode,
    object_kind: objectKind,
    object_id: objectAttributes.id || payload.object_id || Math.floor(Math.random() * 10000),
    action: payload.action || objectAttributes.action || 'update',
    actor_id: actor,
    event_time: eventTime,
    created_at: createdAt,
    due_date: objectAttributes.due_date || null,
    labels: labels,
    is_bug: isBug,
    title: objectAttributes.title || payload.title || 'GitLab Event'
  };
};
